export function renderScorecard(world, { percent, seconds, gag, delivered }) {
  const image = document.createElement("canvas");
  image.width = 1200;
  image.height = 850;
  const pen = image.getContext("2d");
  const horizontal = world.width > world.height;
  const scale = horizontal ? Math.max(1200 / world.width, 850 / world.height) : 1_010 / world.height;
  const width = world.width * scale;
  const height = world.height * scale;
  const left = horizontal ? (1200 - width) * .71 : 914 - width / 2;
  pen.fillStyle = "#100a19";
  pen.fillRect(0, 0, 1200, 850);
  pen.drawImage(world, left, (850 - height) * .47, width, height);
  const shade = pen.createLinearGradient(0, 0, 1200, 0);
  shade.addColorStop(0, "#100a19");
  shade.addColorStop(.51, "#100a19f3");
  shade.addColorStop(.76, "#100a191c");
  shade.addColorStop(1, "#100a1940");
  pen.fillStyle = shade;
  pen.fillRect(0, 0, 1200, 850);
  pen.fillStyle = "#14f195";
  pen.fillRect(48, 52, 55, 5);
  pen.fillStyle = "#fff1db";
  pen.font = "700 23px monospace";
  pen.fillText("BREAKPOINT AFTER HOURS", 48, 102);
  pen.font = '400 85px "Archivo Black", sans-serif';
  pen.fillText("BREAK", 44, 217);
  pen.fillStyle = "#14f195";
  pen.fillText("PINT.", 44, 299);
  pen.font = '400 194px "Archivo Black", sans-serif';
  pen.fillStyle = "#fff1db";
  pen.fillText(String(percent), 39, 505);
  const labelWidth = pen.measureText(String(percent)).width;
  pen.font = '400 78px "Archivo Black", sans-serif';
  pen.fillStyle = "#14f195";
  pen.fillText("%", 52 + labelWidth, 430);
  pen.font = "700 32px DM Sans, sans-serif";
  pen.fillStyle = "#fff1db";
  pen.fillText(delivered ? "of a pint delivered" : "of a pint left", 50, 557);
  pen.fillStyle = "#ffc07c";
  pen.fillText(gag, 50, 612, 578);
  pen.font = "700 24px monospace";
  pen.fillStyle = "#d2c4d7";
  pen.fillText(`${seconds}s · PUB RUN`, 50, 661);
  pen.strokeStyle = "#d2c4d76b";
  pen.beginPath();
  pen.moveTo(48, 745);
  pen.lineTo(1152, 745);
  pen.stroke();
  pen.fillStyle = "#fff1db";
  pen.fillText("breakpoint.beer/break-pint", 48, 796);
  return new Promise((resolve) => image.toBlob(resolve, "image/png"));
}
